// The old Chirpy blog installed a service worker (this URL) that served pages from its
// own cache before the network. This replacement takes over from it, deletes that cache,
// unregisters itself and reloads any open tab, so returning readers reach the redirect
// pages (and then tech.3zcs.me) instead of a cached copy of the old blog.
self.addEventListener("install", function () {
  self.skipWaiting();
});
self.addEventListener("activate", function (event) {
  event.waitUntil(
    caches.keys()
      .then(function (keys) {
        return Promise.all(keys.map(function (key) { return caches.delete(key); }));
      })
      .then(function () { return self.registration.unregister(); })
      .then(function () { return self.clients.matchAll({ type: "window" }); })
      .then(function (clients) {
        clients.forEach(function (client) { client.navigate(client.url); });
      })
  );
});
